import React, {useState } from 'react';
import { useNavigate } from 'react-router-dom';

function AddWarehouseOrderForm({addOrder}) {
    // Declare a state variable to store information about the supplier
    // With an initial empty string value "set..."
    // to update the information state
    const [ordernr, setOrdernr] = useState("");
    const [warehousenr, setWarehousenr] = useState("");
    const [suppliernr, setSuppliernr] = useState("");
    const [orderdate, setOrderdate] = useState("");
    const [statusnr, setStatusnr] = useState("");
    const [deliverydate, setdeliverydate] = useState("");
        
    const navigate = useNavigate();

    // Hämta employeeID från authorisedUser i localStorage
    const authorisedUserStr = localStorage.getItem("authorisedUser");
    const authorisedUser = authorisedUserStr ? JSON.parse(authorisedUserStr) : null;
    const employeenr = authorisedUser ? authorisedUser.employeenr : null;

    const handleSubmit = async (e) => {
        };

    return (
        <form onSubmit={handleSubmit}>

            <h1> Add a New Warehouse Order</h1>

            

            <div className='formField'>
                <label>Order date </label>
                <input
                    type="text"
                    value={orderdate}
                    onChange={(e) => setOrderdate(e.target.value)}
                    className='shortInputField'
                />
            </div>

            <div className='formField'>
                <label>Status nr </label>
                <input
                    type="text"
                    value={statusnr}
                    onChange={(e) => setStatusnr(e.target.value)}
                    className='shortInputField'
                />
            </div>

            <div className='formField'>
                <label>Website: </label>
                <input
                    type="url"
                    value={website}
                    onChange={handleWebsiteChange} // using the custom handle function 
                        placeholder="www.example.com"
                        required
                        className='longInputField'
                    />
                </div>
                <div className='formField'>
                    <label>Phone Number: </label>
                    <input 
                        type="tel"
                        value={phone}
                        onChange={(e) => setPhone(e.target.value)}
                        className='shortInputField'
                    />
                </div>

            
            
            <div className='formField'>
                <label>Email: </label>
                <input
                    type="email"
                    value={email}
                    onChange={(e) => setEmail(e.target.value)}
                    className='longInputField'
                />
            </div>

            <div className='formField'>
                <label>Street: </label>
                <input
                    type="text"
                    value={street}
                    onChange={(e) => setStreet(e.target.value)}
                    className='longInputField'
                />
            </div>

            <div className='twoFieldsHolder'>

                <div className='formField'>
                    <label>City: </label>
                    <input
                        type="text"
                        value={city}
                        onChange={(e) => setCity(e.target.value)}
                        className='shortInputField'
                    />
                </div>
                 <div className='formField'>
                    <label>Post Code: </label>
                    <input
                        type="text"
                        value={postCode}
                        onChange={(e) => setPostCode(e.target.value)}
                        className='shortInputField'
                    />
                </div>

            </div>

            <div className='formField'>
                <label>Country: </label>
                <input
                    type="text"
                    value={country}
                    onChange={(e) => setCountry(e.target.value)}
                    className='shortInputField'
                />
            </div>
            
            <div className='formField'>
                <label>Additional Notes: </label>
                <textarea
                    value={notes}
                    onChange={(e) => setNotes(e.target.value)}
                    className='longInputField'
                />
            </div>
            <button className='addBtn' type="submit">Add Supplier</button>
        </form>

        
    );
}

export default AddWarehouseOrderForm;
